const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const files={"src/app/layout.tsx": "import '@/components/accessibility/accessibility.css';\nimport { SiteAnalyticsTracker } from '@/components/analytics/SiteAnalyticsTracker';\n\nimport { AccessibilityProvider } from '@/components/accessibility/AccessibilityProvider';\nimport '@/components/explorer/explorer-mobile.css';\n\nimport type { Metadata, Viewport } from 'next';\nimport { GeistSans } from 'geist/font/sans';\nimport { GeistMono } from 'geist/font/mono';\nimport './globals.css';\n\nexport const metadata: Metadata = {\n  title: 'A-Factor STEM Studio — Physics simulations for every curriculum',\n  description: 'AI-powered interactive physics simulations for WAEC, NECO, IGCSE, SAT and JUPEB students. Type a prompt, get an instant simulation.',\n  keywords: ['physics simulation', 'WAEC', 'IGCSE', 'NECO', 'SAT', 'JUPEB', 'STEM education', 'Africa'],\n};\n\nexport const viewport: Viewport = {\n  width: 'device-width',\n  initialScale: 1,\n  maximumScale: 5,\n};\n\nexport default function RootLayout({ children }: { children: React.ReactNode }) {\n  return (\n    <html lang=\"en\" className={`${GeistSans.variable} ${GeistMono.variable} antialiased`}>\n      <body className=\"min-h-screen bg-gray-50\" suppressHydrationWarning><AccessibilityProvider>{children}<SiteAnalyticsTracker/></AccessibilityProvider></body>\n    </html>\n  );\n}\n", "src/components/layout/MinitabBar.tsx": "'use client';\nimport { useState, useEffect, useRef } from 'react';\nimport Link from 'next/link';\nimport { usePathname, useRouter } from 'next/navigation';\n\nexport function MinitabBar() {\n  const pathname = usePathname();\n  const router = useRouter();\n  const [loggingOut, setLoggingOut] = useState(false);\n  const tracked = useRef<string | null>(null);\n\n  // Fire a visit beacon once per page load — skipped on the login page and\n  // anything under /minitab/admin, since neither is a \"simulation visit\",\n  // and the admin area has its own separate access gate anyway.\n  useEffect(() => {\n    if (pathname === '/minitab/login' || pathname.startsWith('/minitab/admin')) return;\n    try { if(navigator.doNotTrack==='1'||(navigator as Navigator&{globalPrivacyControl?:boolean}).globalPrivacyControl||localStorage.getItem('afactor-analytics-opt-out-v1')==='1')return; }catch{return;}\n    if (tracked.current === pathname) return;\n    tracked.current = pathname;\n    const slug = pathname.replace(/^\\/minitab\\/?/, '') || 'hub';\n    fetch('/api/minitab-track', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ slug }),\n    }).catch(() => {}); // best-effort — a failed beacon shouldn't disrupt the page\n  }, [pathname]);\n\n  // The login page has nothing to log out of yet — hide the bar there.\n  if (pathname === '/minitab/login') return null;\n\n  const isHub = pathname === '/minitab';\n\n  const logout = async () => {\n    setLoggingOut(true);\n    try {\n      await fetch('/api/minitab-auth', { method: 'DELETE' });\n    } finally {\n      router.push('/minitab/login');\n      router.refresh();\n    }\n  };\n\n  return (\n    <div className=\"bg-indigo-600 text-white\">\n      <div className=\"mx-auto max-w-[100rem] px-4 sm:px-6 h-9 flex items-center justify-between text-xs\">\n        {isHub ? (\n          <span className=\"opacity-90\">PHY 403 Student Area</span>\n        ) : (\n          <Link href=\"/minitab\" className=\"opacity-90 hover:opacity-100 flex items-center gap-1\">\n            <span aria-hidden>←</span> Simulation Library\n          </Link>\n        )}\n        <button\n          onClick={logout}\n          disabled={loggingOut}\n          className=\"opacity-90 hover:opacity-100 underline underline-offset-2 disabled:opacity-50\"\n        >\n          {loggingOut ? 'Logging out…' : 'Logout'}\n        </button>\n      </div>\n    </div>\n  );\n}\n", "src/components/analytics/SiteAnalyticsTracker.tsx": "'use client';\nimport {useEffect,useRef,useState} from 'react';\nimport {usePathname} from 'next/navigation';\nimport {sitePath,type SiteKind} from '@/lib/analytics/site-model';\nconst OPT='afactor-analytics-opt-out-v1';\nexport function analyticsAllowed(){try{return navigator.doNotTrack!=='1'&&!(navigator as Navigator&{globalPrivacyControl?:boolean}).globalPrivacyControl&&localStorage.getItem(OPT)!=='1';}catch{return false;}}\n// Serialising beacons lets the first response set the browser cookie before later events.\nlet queue:Promise<unknown>=Promise.resolve();\nfunction send(body:object){const task=queue.then(async()=>{if(!analyticsAllowed())return false;try{const r=await fetch('/api/site-track',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),keepalive:true});return r.ok&&(await r.json()).accepted===true;}catch{return false;}});queue=task.catch(()=>false);return task;}\nexport function SiteAnalyticsTracker(){\n const pathname=usePathname();const [preference,setPreference]=useState(0);const page=useRef<{path:string;id:string}|null>(null);\n useEffect(()=>{const change=()=>{page.current=null;setPreference(n=>n+1);};window.addEventListener('afactor-analytics-preference',change);return()=>window.removeEventListener('afactor-analytics-preference',change);},[]);\n useEffect(()=>{\n  if(!sitePath(pathname)||!analyticsAllowed())return;\n  if(page.current?.path!==pathname)page.current={path:pathname,id:crypto.randomUUID()};\n  const viewId=page.current.id;const referrer=document.referrer;let milliseconds=0,last=performance.now(),visible=document.visibilityState==='visible'&&document.hasFocus();\n  const accepted=send({kind:'pageview',path:pathname,id:viewId,viewId,referrer});\n  function accrue(){const now=performance.now();if(visible)milliseconds+=Math.max(0,now-last);last=now;}\n  function flush(){accrue();const seconds=Math.min(1800,Math.floor(milliseconds/1000));if(seconds>0)void accepted.then(ok=>ok&&send({kind:'engagement',path:pathname,id:crypto.randomUUID(),viewId,seconds}));}\n  function visibility(){flush();visible=document.visibilityState==='visible'&&document.hasFocus();last=performance.now();}\n  function action(e:MouseEvent){const button=(e.target as Element|null)?.closest('button');if(!button?.closest('[data-simulation-stage]'))return;const label=button.textContent?.trim()||'';let kind:SiteKind|undefined;\n   if(/^(?:▶\\s*)?run$/i.test(label))kind='run';else if(/pause|resume/i.test(label))kind='pause';else if(/reset/i.test(label))kind='reset';else if(/expand simulation|exit classroom/i.test(label))kind='classroom';\n   if(kind)void accepted.then(ok=>ok&&send({kind,path:pathname,id:crypto.randomUUID(),viewId}));\n  }\n  const timer=setInterval(flush,60000);document.addEventListener('visibilitychange',visibility);window.addEventListener('focus',visibility);window.addEventListener('blur',visibility);window.addEventListener('pagehide',flush);document.addEventListener('click',action);\n  return()=>{flush();clearInterval(timer);document.removeEventListener('visibilitychange',visibility);window.removeEventListener('focus',visibility);window.removeEventListener('blur',visibility);window.removeEventListener('pagehide',flush);document.removeEventListener('click',action);};\n },[pathname,preference]);return null;\n}\n", "src/lib/analytics/redis.ts": "import { Redis } from '@upstash/redis';\n\n// Analytics are best-effort: if Upstash isn't configured (env vars missing),\n// every function here silently no-ops rather than breaking login or page\n// loads. A lecturer's activity dashboard is a nice-to-have, not something\n// that should ever be able to lock a student out of a simulation.\n\nlet client: Redis | null = null;\nfunction getClient(): Redis | null {\n  if (client) return client;\n  // Two naming conventions exist depending on how the database was connected:\n  // UPSTASH_REDIS_REST_* if you pasted credentials from upstash.com directly,\n  // or KV_REST_API_* if you connected it via Vercel's Storage tab (Vercel\n  // injects these automatically into every deployment once connected, so\n  // checking both means production works with zero extra config either way).\n  const url = process.env.UPSTASH_REDIS_REST_URL ?? process.env.KV_REST_API_URL;\n  const token = process.env.UPSTASH_REDIS_REST_TOKEN ?? process.env.KV_REST_API_TOKEN;\n  if (!url || !token) return null;\n  client = new Redis({ url, token, signal:()=>AbortSignal.timeout(5000) });\n  return client;\n}\n\nconst MAX_EVENTS = 500; // capped list — plenty for a single-course classroom tool, keeps well inside the free tier's 256MB\n\n/** Trims, collapses whitespace, and caps length. Students self-report this — it's a\n * display label, not a verified identity, so no uniqueness or format is enforced. */\nexport function sanitizeName(raw: string): string {\n  return raw.trim().replace(/\\s+/g, ' ').slice(0, 40);\n}\n\nexport async function recordLogin(name: string): Promise<void> {\n  const redis = getClient();\n  if (!redis) return;\n  try {\n    const event = JSON.stringify({ t: Date.now(), name });\n    await Promise.all([\n      redis.incr('minitab:logins:count'),\n      redis.lpush('minitab:logins:events', event),\n      redis.ltrim('minitab:logins:events', 0, MAX_EVENTS - 1),\n      redis.sadd('minitab:students', name),\n      redis.incr(`minitab:student:${name}:logins`),\n    ]);\n  } catch (error) {\n    console.error('[analytics] recordLogin failed', error);\n  }\n}\n\nexport async function recordVisit(slug: string, sessionId: string | undefined, name: string | undefined): Promise<void> {\n  const redis = getClient();\n  if (!redis) return;\n  try {\n    const event = JSON.stringify({ t: Date.now(), slug, name });\n    const ops: Promise<unknown>[] = [\n      redis.incr(`minitab:visits:count:${slug}`),\n      redis.lpush('minitab:visits:events', event),\n      redis.ltrim('minitab:visits:events', 0, MAX_EVENTS - 1),\n    ];\n    if (sessionId) ops.push(redis.sadd('minitab:sessions', sessionId));\n    if (name) {\n      ops.push(redis.sadd('minitab:students', name));\n      ops.push(redis.incr(`minitab:student:${name}:visits`));\n      ops.push(redis.set(`minitab:student:${name}:last`, Date.now()));\n    }\n    await Promise.all(ops);\n  } catch (error) {\n    console.error('[analytics] recordVisit failed', error);\n  }\n}\n\nexport interface StudentSummary {\n  name: string;\n  logins: number;\n  visits: number;\n  lastActive: number | null;\n}\n\nexport interface AnalyticsSummary {\n  configured: boolean;\n  totalLogins: number;\n  distinctSessions: number;\n  visitsBySlug: { slug: string; count: number }[];\n  students: StudentSummary[];\n  recentEvents: { t: number; kind: 'login' | 'visit'; slug?: string; name?: string }[];\n}\n\n// Every simulation slug currently in the minitab, so the dashboard can show\n// a zero-count row for ones nobody's opened yet, not just the ones with hits.\nconst KNOWN_SLUGS = [\n  'gradient-explorer', 'div-stokes', 'eigenvector-explorer', 'gamma-function',\n  'legendre-bessel', 'hermite-laguerre-delta', 'fourier-series',\n  'fourier-transform', 'damped-oscillator',\n];\n\nexport async function getAnalyticsSummary(): Promise<AnalyticsSummary> {\n  const redis = getClient();\n  if (!redis) {\n    return { configured: false, totalLogins: 0, distinctSessions: 0, visitsBySlug: [], students: [], recentEvents: [] };\n  }\n  try {\n    const [totalLogins, distinctSessions, loginEventsRaw, visitEventsRaw, studentNames, ...counts] = await Promise.all([\n      redis.get<number>('minitab:logins:count'),\n      redis.scard('minitab:sessions'),\n      redis.lrange('minitab:logins:events', 0, 49),\n      redis.lrange('minitab:visits:events', 0, 49),\n      redis.smembers('minitab:students'),\n      ...KNOWN_SLUGS.map(slug => redis.get<number>(`minitab:visits:count:${slug}`)),\n    ]);\n\n    const visitsBySlug = KNOWN_SLUGS.map((slug, i) => ({ slug, count: counts[i] ?? 0 }))\n      .sort((a, b) => b.count - a.count);\n\n    const names = (studentNames as string[]) ?? [];\n    const studentStats = await Promise.all(\n      names.map(async (name) => {\n        const [logins, visits, last] = await Promise.all([\n          redis.get<number>(`minitab:student:${name}:logins`),\n          redis.get<number>(`minitab:student:${name}:visits`),\n          redis.get<number>(`minitab:student:${name}:last`),\n        ]);\n        return { name, logins: logins ?? 0, visits: visits ?? 0, lastActive: last ?? null };\n      })\n    );\n    const students = studentStats.sort((a, b) => (b.lastActive ?? 0) - (a.lastActive ?? 0));\n\n    type RawEvent = { t: number; slug?: string; name?: string };\n    const parseEvents = (raw: unknown[], kind: 'login' | 'visit') =>\n      raw.map(r => {\n        const parsed: RawEvent = typeof r === 'string' ? JSON.parse(r) : (r as RawEvent);\n        return { t: parsed.t, kind, slug: parsed.slug, name: parsed.name };\n      });\n\n    const recentEvents = [...parseEvents(loginEventsRaw, 'login'), ...parseEvents(visitEventsRaw, 'visit')]\n      .sort((a, b) => b.t - a.t)\n      .slice(0, 50);\n\n    return {\n      configured: true,\n      totalLogins: totalLogins ?? 0,\n      distinctSessions: distinctSessions ?? 0,\n      visitsBySlug,\n      students,\n      recentEvents,\n    };\n  } catch (error) {\n    console.error('[analytics] getAnalyticsSummary failed', error);\n    return { configured: true, totalLogins: 0, distinctSessions: 0, visitsBySlug: [], students: [], recentEvents: [] };\n  }\n}\n", "src/lib/analytics/site-auth.ts": "import {createHmac,randomUUID,timingSafeEqual} from 'node:crypto';\nimport type {NextRequest} from 'next/server';\nimport {hashPasscode,MINITAB_ADMIN_COOKIE,MINITAB_COOKIE,MINITAB_NAME_COOKIE} from '@/lib/utils/minitabAuth';\nexport const SITE_VISITOR_COOKIE='af_site_vid',SITE_SESSION_COOKIE='af_site_sid',SITE_OPTOUT_COOKIE='af_analytics_optout';\nexport function analyticsSecret(){return process.env.ANALYTICS_HASH_SECRET||process.env.MINITAB_ADMIN_PASSCODE||'';}\nexport function sameSecret(a:string,b:string){const x=Buffer.from(a),y=Buffer.from(b);return x.length===y.length&&timingSafeEqual(x,y);}\nexport async function siteAdmin(req:NextRequest){const pass=process.env.MINITAB_ADMIN_PASSCODE;return !!pass&&sameSecret(req.cookies.get(MINITAB_ADMIN_COOKIE)?.value||'',await hashPasscode(pass));}\nfunction mac(value:string){return createHmac('sha256',analyticsSecret()).update(value).digest('hex');}\nexport function signedAnalyticsId(cookie:string|undefined){\n if(cookie){const [id,signature]=cookie.split('.');if(/^[a-f0-9-]{36}$/.test(id||'')&&sameSecret(signature||'',mac(id)))return {id,cookie,fresh:false};}\n const id=randomUUID();return{id,cookie:id+'.'+mac(id),fresh:true};\n}\nexport function analyticsVisitorKey(id:string){return mac('visitor:'+id);}\nexport async function analyticsName(req:NextRequest){\n const pass=process.env.MINITAB_PASSCODE;if(!pass||!sameSecret(req.cookies.get(MINITAB_COOKIE)?.value||'',await hashPasscode(pass)))return'';\n try{return decodeURIComponent(req.cookies.get(MINITAB_NAME_COOKIE)?.value||'').replace(/[\\x00-\\x1f\\x7f]/g,'').trim().replace(/\\s+/g,' ').slice(0,40);}catch{return'';}\n}\nexport function optedOut(req:NextRequest){return req.cookies.get(SITE_OPTOUT_COOKIE)?.value==='1'||req.headers.get('dnt')==='1'||req.headers.get('sec-gpc')==='1';}\n", "src/lib/analytics/site-pages.json": "{\n  \"/mathematics\": \"Mathematics\",\n  \"/geophysics\": \"Geophysics\",\n  \"/tutor\": \"Tutor\",\n  \"/simulations\": \"Simulations\",\n  \"/explore\": \"Explore\",\n  \"/minitab\": \"Minitab\",\n  \"/biology\": \"Biology\",\n  \"/chemistry\": \"Chemistry\",\n  \"/about\": \"About\",\n  \"/mathematics/unit-circle\": \"Unit circle\",\n  \"/geophysics/earth\": \"Earth explorer\",\n  \"/geophysics/solar\": \"Solar system explorer\",\n  \"/geophysics/lab\": \"Geophysics field lab\",\n  \"/geophysics/tectonics\": \"Plate tectonics\",\n  \"/simulations/polarization\": \"Polarization\",\n  \"/simulations/bjt-transistor\": \"BJT transistor\",\n  \"/simulations/vectors\": \"Vectors\",\n  \"/simulations/refraction\": \"Refraction\",\n  \"/simulations/consequences-of-motion\": \"Consequences of motion\",\n  \"/simulations/electromagnetic-induction\": \"Electromagnetic induction\",\n  \"/simulations/pn-junction\": \"PN junction\",\n  \"/simulations/reflection\": \"Reflection\",\n  \"/simulations/projectile-motion\": \"Projectile motion\",\n  \"/simulations/rectilinear-propagation\": \"Light, shadows and pinholes\",\n  \"/simulations/friction\": \"Friction\",\n  \"/simulations/coupled-oscillators\": \"Coupled oscillators\",\n  \"/simulations/quantum-harmonic-oscillator\": \"Quantum harmonic oscillator\",\n  \"/simulations/diffraction\": \"Diffraction\",\n  \"/simulations/ac-circuits\": \"AC circuits\",\n  \"/simulations/elasticity\": \"Elasticity\",\n  \"/simulations/de-broglie\": \"De Broglie waves\",\n  \"/simulations/double-pendulum\": \"Double pendulum\",\n  \"/simulations/heat-transfer\": \"Heat transfer\",\n  \"/simulations/mosfet\": \"MOSFET\",\n  \"/simulations/electrostatics-fields\": \"Electric fields\",\n  \"/simulations/ohms-law\": \"Ohm’s law and circuits\",\n  \"/simulations/magnetic-effects\": \"Magnetic effects\",\n  \"/simulations/gas-laws\": \"Gas laws\",\n  \"/simulations/space\": \"Space and displacement\",\n  \"/simulations/unit-circle\": \"Unit Circle\",\n  \"/simulations/quantum-tunneling\": \"Quantum tunneling\",\n  \"/simulations/atomic-models\": \"Atomic models\",\n  \"/simulations/waves\": \"Waves\",\n  \"/simulations/photoelectric-effect\": \"Photoelectric effect\",\n  \"/simulations/electrostatics-potential\": \"Electric potential and capacitance\",\n  \"/simulations/newtons-laws\": \"Newton’s laws\",\n  \"/simulations/oscillations\": \"Oscillations\",\n  \"/simulations/radioactive-decay\": \"Radioactive decay\",\n  \"/simulations/band-theory\": \"Band theory\",\n  \"/simulations/x-rays\": \"X-rays\",\n  \"/simulations/electrostatics-charging\": \"Electrostatic charging\",\n  \"/simulations/equilibrium-of-forces\": \"Equilibrium of forces\",\n  \"/minitab/fourier-series\": \"Fourier series\",\n  \"/minitab/fourier-transform\": \"Fourier transform\",\n  \"/minitab/hermite-laguerre-delta\": \"Hermite, Laguerre and delta\",\n  \"/minitab/gamma-function\": \"Gamma function\",\n  \"/minitab/gradient-explorer\": \"Gradient explorer\",\n  \"/minitab/div-stokes\": \"Divergence and Stokes theorems\",\n  \"/minitab/legendre-bessel\": \"Legendre and Bessel functions\",\n  \"/minitab/damped-oscillator\": \"Damped oscillator\",\n  \"/minitab/eigenvector-explorer\": \"Eigenvector explorer\",\n  \"/embed/polarization\": \"Polarization\",\n  \"/embed/bjt-transistor\": \"Bjt Transistor\",\n  \"/embed/optics\": \"Optics\",\n  \"/embed/meiosis\": \"Meiosis\",\n  \"/embed/decay\": \"Decay\",\n  \"/embed/vectors\": \"Vectors\",\n  \"/embed/life-processes\": \"Life Processes\",\n  \"/embed/electromagnetic-induction\": \"Electromagnetic Induction\",\n  \"/embed/circuits\": \"Circuits\",\n  \"/embed/pn-junction\": \"Pn Junction\",\n  \"/embed/reflection\": \"Reflection\",\n  \"/embed/rectilinear-propagation\": \"Rectilinear Propagation\",\n  \"/embed/friction\": \"Friction\",\n  \"/embed/coupled-oscillators\": \"Coupled Oscillators\",\n  \"/embed/quantum-harmonic-oscillator\": \"Quantum Harmonic Oscillator\",\n  \"/embed/diffraction\": \"Diffraction\",\n  \"/embed/ac-circuits\": \"Ac Circuits\",\n  \"/embed/xrays\": \"Xrays\",\n  \"/embed/elasticity\": \"Elasticity\",\n  \"/embed/double-pendulum\": \"Double Pendulum\",\n  \"/embed/cells\": \"Cells\",\n  \"/embed/debroglie\": \"Debroglie\",\n  \"/embed/classification\": \"Classification\",\n  \"/embed/skeletal-system\": \"Skeletal System\",\n  \"/embed/projectile\": \"Projectile\",\n  \"/embed/mosfet\": \"Mosfet\",\n  \"/embed/electrostatics-fields\": \"Electrostatics Fields\",\n  \"/embed/damped-oscillator\": \"Damped Oscillator\",\n  \"/embed/magnetic-effects\": \"Magnetic Effects\",\n  \"/embed/space\": \"Space\",\n  \"/embed/heat\": \"Heat\",\n  \"/embed/unit-circle\": \"Unit Circle\",\n  \"/embed/quantum-tunneling\": \"Quantum Tunneling\",\n  \"/embed/atomic-models\": \"Atomic Models\",\n  \"/embed/photoelectric\": \"Photoelectric\",\n  \"/embed/waves\": \"Waves\",\n  \"/embed/electrostatics-potential\": \"Electrostatics Potential\",\n  \"/embed/mitosis\": \"Mitosis\",\n  \"/embed/oscillations\": \"Oscillations\",\n  \"/embed/equilibrium\": \"Equilibrium\",\n  \"/embed/transpiration\": \"Transpiration\",\n  \"/embed/band-theory\": \"Band Theory\",\n  \"/embed/electrostatics-charging\": \"Electrostatics Charging\",\n  \"/biology/meiosis\": \"Meiosis and genetic variation\",\n  \"/biology/life-processes\": \"Characteristics of living things\",\n  \"/biology/cells\": \"Cells and organelles\",\n  \"/biology/classification\": \"Classification and scientific names\",\n  \"/biology/skeletal-system\": \"Human skeletal system\",\n  \"/biology/mitosis\": \"Mitosis and the cell cycle\",\n  \"/biology/transpiration\": \"Transpiration in plants\",\n  \"/chemistry/compound-builder\": \"Compound builder\",\n  \"/chemistry/crystal-builder\": \"Crystal builder\",\n  \"/chemistry/nuclear\": \"Nuclear playground\",\n  \"/chemistry/perovskite-lab\": \"Perovskite lab\",\n  \"/chemistry/heusler\": \"Heusler alloys\",\n  \"/chemistry/periodic-table\": \"Periodic table\",\n  \"/chemistry/organic\": \"Organic molecules\",\n  \"/\": \".\"\n}\n", "src/lib/analytics/site-model.ts": "import pages from './site-pages.json';\nexport const SITE_RETENTION_DAYS=90;\nexport const SITE_PATHS:Record<string,string>=pages;\nexport type SiteKind='pageview'|'engagement'|'run'|'pause'|'reset'|'classroom';\nexport const siteKinds:SiteKind[]=['pageview','engagement','run','pause','reset','classroom'];\nexport function sitePath(raw:unknown):string|null {\n if(typeof raw!=='string'||raw.length>180||raw.includes('?')||raw.includes('#'))return null;\n const p=raw==='/'?raw:raw.replace(/\\/$/,'');return Object.hasOwn(SITE_PATHS,p)?p:null;\n}\nexport function siteSubject(path:string){if(path.startsWith('/embed/'))return'Embedded activities';if(path.startsWith('/simulations'))return'Physics';if(path.startsWith('/geophysics'))return'Geophysics';if(path.startsWith('/mathematics'))return'Mathematics';if(path.startsWith('/chemistry'))return'Chemistry';if(path.startsWith('/biology'))return'Biology';if(path.startsWith('/minitab'))return'Minitab';return'Site navigation';}\nexport function dateKeys(days:number,now=Date.now()){const end=new Date(now);end.setUTCHours(0,0,0,0);return Array.from({length:days},(_,i)=>new Date(end.getTime()-(days-1-i)*86400000).toISOString().slice(0,10));}\nexport function csvCell(value:unknown){let s=String(value??'');if(/^[\\s]*[=+\\-@\\t\\r]/.test(s))s=\"'\"+s;return '\"'+s.replace(/\"/g,'\"\"')+'\"';}\nexport type SiteRow={key:string;count:number};\nexport type SitePerson={id:string;name:string;last:number;path:string;device:string};\nexport type SiteEvent={t:number;kind:SiteKind;path:string;visitor:string;name:string;device:string};\nexport type SiteSummary={configured:boolean;days:number;views:number;visitors:number;sessions:number;seconds:number;pages:(SiteRow&{title:string;seconds:number})[];subjects:SiteRow[];devices:SiteRow[];referrers:SiteRow[];actions:SiteRow[];daily:{day:string;views:number;seconds:number}[];people:SitePerson[];recent:SiteEvent[]};\nexport type SitePersonDetail={person:SitePerson|null;pages:(SiteRow&{title:string;seconds:number})[];views:number;seconds:number};\n", "src/lib/analytics/site-store.ts": "import {Redis} from '@upstash/redis';\nimport {SITE_PATHS,SITE_RETENTION_DAYS,dateKeys,siteSubject,type SiteKind,type SiteRow,type SiteSummary,type SitePerson,type SitePersonDetail,type SiteEvent} from './site-model';\nconst P='afsite:v1:',TTL=95*86400;\nlet client:Redis|null=null;\nexport function siteRedis(){\n if(client)return client;\n const url=process.env.UPSTASH_REDIS_REST_URL??process.env.KV_REST_API_URL,token=process.env.UPSTASH_REDIS_REST_TOKEN??process.env.KV_REST_API_TOKEN;\n if(!url||!token)return null;\n client=new Redis({url,token,signal:()=>AbortSignal.timeout(5000)});return client;\n}\n// One atomic update prevents duplicate beacons and concurrent time reports from overcounting.\nexport const RECORD_SITE_LUA=`\nlocal e=cjson.decode(ARGV[1])\nlocal n=redis.call('INCR',KEYS[1]); redis.call('EXPIRE',KEYS[1],70)\nif n>120 then return -1 end\nif not redis.call('SET',KEYS[2],'1','NX','EX',600) then return 0 end\nif e.kind=='engagement' then\n if redis.call('HGET',KEYS[3],'visitor')~=e.visitor or redis.call('HGET',KEYS[3],'path')~=e.path then return 0 end\n local prior=tonumber(redis.call('HGET',KEYS[3],'seconds') or '0')\n local seconds=math.min(1800,math.max(0,math.floor(e.seconds)))\n local delta=seconds-prior\n if delta<=0 then return 0 end\n redis.call('HSET',KEYS[3],'seconds',seconds)\n redis.call('HINCRBY',KEYS[4],'seconds',delta)\n redis.call('HINCRBY',KEYS[6],e.path,delta)\n redis.call('HINCRBY',KEYS[13],e.path,delta)\n for _,i in ipairs({4,6,13}) do redis.call('EXPIRE',KEYS[i],e.ttl) end\n return 1\nend\nif e.kind=='pageview' then\n if redis.call('EXISTS',KEYS[3])==1 then return 0 end\n redis.call('HSET',KEYS[3],'visitor',e.visitor,'path',e.path,'seconds',0)\n redis.call('EXPIRE',KEYS[3],86400)\n redis.call('HINCRBY',KEYS[4],'views',1)\n redis.call('HINCRBY',KEYS[5],e.path,1)\n redis.call('HINCRBY',KEYS[7],e.subject,1)\n redis.call('HINCRBY',KEYS[8],e.device,1)\n redis.call('HINCRBY',KEYS[9],e.referrer,1)\n redis.call('PFADD',KEYS[10],e.visitor)\n redis.call('PFADD',KEYS[11],e.session)\n redis.call('HINCRBY',KEYS[12],e.path,1)\n for _,i in ipairs({4,5,7,8,9,10,11,12}) do redis.call('EXPIRE',KEYS[i],e.ttl) end\nelse\n redis.call('HINCRBY',KEYS[4],e.kind,1); redis.call('EXPIRE',KEYS[4],e.ttl)\nend\nredis.call('HSET',KEYS[14],'id',e.visitor,'name',e.name,'last',e.t,'path',e.path,'device',e.device)\nredis.call('EXPIRE',KEYS[14],e.ttl)\nredis.call('ZADD',KEYS[15],e.t,e.visitor)\nredis.call('ZREMRANGEBYSCORE',KEYS[15],'-inf',e.cutoff)\nredis.call('EXPIRE',KEYS[15],e.ttl)\nredis.call('LPUSH',KEYS[16],cjson.encode({t=e.t,kind=e.kind,path=e.path,visitor=e.visitor,name=e.name,device=e.device}))\nredis.call('LTRIM',KEYS[16],0,199); redis.call('EXPIRE',KEYS[16],e.ttl)\nreturn 1`;\nexport type SiteRecord={id:string;viewId:string;visitor:string;session:string;path:string;kind:SiteKind;seconds:number;name:string;device:string;referrer:string};\nexport async function recordSite(e:SiteRecord,redis=siteRedis(),now=Date.now()){\n if(!redis)return null;const day=new Date(now).toISOString().slice(0,10);\n const keys=[P+'rate:'+e.session+':'+Math.floor(now/60000),P+'dedupe:'+e.session+':'+e.id,P+'view:'+e.viewId,P+'day:'+day,P+'pages:'+day,P+'page-time:'+day,P+'subjects:'+day,P+'devices:'+day,P+'refs:'+day,P+'visitors:'+day,P+'sessions:'+day,P+'person-pages:'+day+':'+e.visitor,P+'person-time:'+day+':'+e.visitor,P+'person:'+e.visitor,P+'people',P+'recent'];\n return Number(await redis.eval(RECORD_SITE_LUA,keys,[JSON.stringify({...e,t:now,ttl:TTL,cutoff:now-SITE_RETENTION_DAYS*86400000,subject:siteSubject(e.path)})]));\n}\nfunction sum(records:unknown[]){const result:Record<string,number>=Object.create(null);for(const record of records)for(const [key,value]of Object.entries((record||{})as Record<string,unknown>)){const n=Number(value);if(Number.isFinite(n))result[key]=(result[key]||0)+n;}return result;}\nfunction rows(counts:Record<string,number>):SiteRow[]{return Object.entries(counts).map(([key,count])=>({key,count})).sort((a,b)=>b.count-a.count);}\nfunction person(raw:unknown):SitePerson|null{if(!raw||typeof raw!=='object')return null;const p=raw as Record<string,unknown>;if(!p.id)return null;return{id:String(p.id),name:String(p.name||''),last:Number(p.last)||0,path:String(p.path||''),device:String(p.device||'')};}\nexport async function siteSummary(days:number,redis=siteRedis()):Promise<SiteSummary>{\n const dates=dateKeys(days);const empty:SiteSummary={configured:false,days,views:0,visitors:0,sessions:0,seconds:0,pages:[],subjects:[],devices:[],referrers:[],actions:[],daily:[],people:[],recent:[]};if(!redis)return empty;\n const pipeline=redis.pipeline();for(const day of dates)for(const group of ['day:','pages:','page-time:','subjects:','devices:','refs:'])pipeline.hgetall(P+group+day);\n const raw=await pipeline.exec();const group=(n:number)=>dates.map((_,i)=>raw[i*6+n]);const totals=sum(group(0)),pageTime=sum(group(2));\n const [visitors,sessions,ids,recentRaw]=await Promise.all([redis.pfcount(P+'visitors:'+dates[0],...dates.slice(1).map(d=>P+'visitors:'+d)),redis.pfcount(P+'sessions:'+dates[0],...dates.slice(1).map(d=>P+'sessions:'+d)),redis.zrange<string[]>(P+'people','+inf',Date.parse(dates[0]+'T00:00:00Z'),{byScore:true,rev:true,offset:0,count:200}),redis.lrange(P+'recent',0,199)]);\n const peoplePipeline=redis.pipeline();for(const id of ids)peoplePipeline.hgetall(P+'person:'+id);const people=ids.length?(await peoplePipeline.exec()).map(person).filter((p):p is SitePerson=>!!p):[];\n const recent:SiteEvent[]=recentRaw.map(r=>typeof r==='string'?JSON.parse(r):r).filter((e:SiteEvent)=>e.t>=Date.parse(dates[0]+'T00:00:00Z')).slice(0,100);\n return{...empty,configured:true,views:totals.views||0,seconds:totals.seconds||0,visitors:Number(visitors),sessions:Number(sessions),pages:rows(sum(group(1))).map(r=>({...r,title:SITE_PATHS[r.key]||r.key,seconds:pageTime[r.key]||0})),subjects:rows(sum(group(3))),devices:rows(sum(group(4))),referrers:rows(sum(group(5))),actions:['run','pause','reset','classroom'].map(key=>({key,count:totals[key]||0})),daily:dates.map((day,i)=>({day,views:Number((raw[i*6]as Record<string,number>|null)?.views)||0,seconds:Number((raw[i*6]as Record<string,number>|null)?.seconds)||0})),people,recent};\n}\nexport async function sitePersonDetail(id:string,days:number,redis=siteRedis()):Promise<SitePersonDetail>{\n if(!redis)return{person:null,pages:[],views:0,seconds:0};const dates=dateKeys(days),p=redis.pipeline();for(const day of dates){p.hgetall(P+'person-pages:'+day+':'+id);p.hgetall(P+'person-time:'+day+':'+id);}const data=await p.exec(),views=sum(data.filter((_,i)=>i%2===0)),times=sum(data.filter((_,i)=>i%2===1));return{person:person(await redis.hgetall(P+'person:'+id)),pages:rows(views).map(r=>({...r,title:SITE_PATHS[r.key]||r.key,seconds:times[r.key]||0})),views:Object.values(views).reduce((a,b)=>a+b,0),seconds:Object.values(times).reduce((a,b)=>a+b,0)};\n}\n", "src/app/about/page.tsx": "import Link from 'next/link';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport Image from 'next/image';\n\nconst STATS = [\n  { value: '25+', label: 'Physics simulations' },\n  { value: '5', label: 'Exam curricula' },\n  { value: '4', label: 'African languages' },\n  { value: '100%', label: 'Free to start' },\n];\n\nconst PORTFOLIO_URL = 'https://mrdof-portfolio.vercel.app/';\n\nconst CURRICULA = [\n  { name: 'WAEC', desc: 'West African Senior School Certificate', color: 'bg-indigo-50 text-indigo-700 border-indigo-100' },\n  { name: 'NECO', desc: 'National Examinations Council (Nigeria)', color: 'bg-pink-50 text-pink-700 border-pink-100' },\n  { name: 'IGCSE', desc: 'Cambridge International General Certificate', color: 'bg-emerald-50 text-emerald-700 border-emerald-100' },\n  { name: 'JUPEB', desc: 'Joint Universities Preliminary Examinations Board', color: 'bg-purple-50 text-purple-700 border-purple-100' },\n  { name: 'SAT', desc: 'Scholastic Assessment Test (US)', color: 'bg-orange-50 text-orange-700 border-orange-100' },\n];\n\nconst TEAM = [\n  {\n    name: 'Fatai',\n    role: 'Founder & CEO',\n    bio: 'Building A-Factor to give every African student access to world-class physics education — regardless of where they live or what they can afford.',\n  },\n];\n\nconst ADVANCED_SIMS = [\n  { name: 'Atomic Models', href: '/simulations/atomic-models', desc: 'From Thomson to Bohr to the quantum model — how our picture of the atom evolved.' },\n  { name: 'Quantum Tunnelling', href: '/simulations/quantum-tunneling', desc: 'Watch a particle pass through a barrier it classically shouldn\\u2019t be able to cross.' },\n  { name: 'Coupled Oscillators', href: '/simulations/coupled-oscillators', desc: 'Normal modes and energy exchange between two linked oscillating systems.' },\n  { name: 'Double Pendulum', href: '/simulations/double-pendulum', desc: 'A deterministic system with genuinely chaotic, unpredictable motion.' },\n];\n\nconst ROADMAP = [\n  { phase: 'Phase 1', status: 'live', title: 'Mechanics & thermal physics', items: ['Projectile motion (all launch modes)', 'Gas laws (Boyle & Charles)', 'Thermal conductivity, convection & radiation', 'Multilingual support (EN, YO, HA, IG)'] },\n  { phase: 'Phase 2', status: 'live', title: 'Electricity & electromagnetism', items: [\"Ohm's law, series & parallel circuits\", 'Electrostatics (charging, fields, potential)', 'Magnetic effects of current', 'Electromagnetic induction & AC circuits'] },\n  { phase: 'Phase 3', status: 'building', title: 'Modern & advanced physics', items: ['Atomic models', 'Quantum tunnelling', 'Coupled oscillators & double pendulum', 'Photoelectric effect & radioactive decay'] },\n  { phase: 'Phase 4', status: 'planned', title: 'Platform & marketplace', items: ['AI-generated exercises', 'Teacher dashboard', 'School LMS integration', 'Student analytics & enterprise plans'] },\n];\n\nconst STATUS_STYLES: Record<string, string> = {\n  live:     'bg-emerald-100 text-emerald-700',\n  building: 'bg-amber-100 text-amber-700',\n  planned:  'bg-gray-100 text-gray-500',\n};\n\nconst STATUS_DOT: Record<string, string> = {\n  live:     'bg-emerald-500',\n  building: 'bg-amber-400',\n  planned:  'bg-gray-300',\n};\n\nexport default function AboutPage() {\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n\n        {/* Hero */}\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-4xl px-4 sm:px-6 py-12 sm:py-16 text-center\">\n            <div className=\"inline-flex items-center gap-2 rounded-full border border-indigo-100 bg-indigo-50 px-4 py-1.5 mb-6\">\n              <span className=\"h-1.5 w-1.5 rounded-full bg-indigo-500 animate-pulse\"/>\n              <span className=\"text-xs font-medium text-indigo-600\">Early access — actively building</span>\n            </div>\n            <h1 className=\"text-2xl sm:text-4xl font-semibold text-gray-900 leading-tight mb-4\">\n              Physics education shouldn&apos;t depend<br className=\"hidden sm:block\" /> on where you were born\n            </h1>\n            <p className=\"text-sm sm:text-base text-gray-500 leading-relaxed max-w-2xl mx-auto mb-8\">\n              A-Factor STEM Studio is an AI-powered physics simulation platform built for\n              secondary school students across Africa and beyond. Type a prompt, get an\n              instant interactive simulation. No programming skills required.\n            </p>\n            <div className=\"flex flex-col sm:flex-row gap-3 justify-center\">\n              <Link href=\"/simulations\"\n                className=\"rounded-xl bg-indigo-600 px-6 py-3 text-sm font-medium text-white hover:bg-indigo-700 transition\">\n                Try a simulation\n              </Link>\n              <Link href=\"/simulations\"\n                className=\"rounded-xl border border-gray-200 bg-white px-6 py-3 text-sm font-medium text-gray-700 hover:bg-gray-50 transition\">\n                Browse all topics\n              </Link>\n            </div>\n          </div>\n        </section>\n\n        {/* Stats */}\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-4xl px-4 sm:px-6 py-8\">\n            <div className=\"grid grid-cols-2 sm:grid-cols-4 gap-6\">\n              {STATS.map(s => (\n                <div key={s.label} className=\"text-center\">\n                  <p className=\"text-2xl sm:text-3xl font-semibold text-indigo-600 mb-1\">{s.value}</p>\n                  <p className=\"text-xs text-gray-500\">{s.label}</p>\n                </div>\n              ))}\n            </div>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-4xl px-4 sm:px-6 py-10 space-y-10\">\n\n          {/* The problem */}\n          <section>\n            <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">The problem</p>\n            <div className=\"grid sm:grid-cols-2 gap-4\">\n              {[\n                { icon: '📚', title: 'Static textbooks', desc: 'Most students learn physics from diagrams that never move. Abstract concepts like projectile motion or gas pressure stay abstract.' },\n                { icon: '💰', title: 'Expensive labs', desc: 'Physical lab equipment is out of reach for most schools in Africa. Students sit exams on experiments they have never performed.' },\n                { icon: '🌍', title: 'Localisation gap', desc: 'Global tools like PhET and GeoGebra are not built for WAEC, NECO, or JUPEB curricula, and offer no support in Yoruba, Hausa, or Igbo.' },\n                { icon: '🤖', title: 'No AI layer', desc: 'No existing simulation platform lets a student describe what they want to see in plain language and instantly get an interactive result.' },\n              ].map(p => (\n                <div key={p.title} className=\"rounded-2xl border border-gray-200 bg-white p-5\">\n                  <span className=\"text-xl mb-3 block\">{p.icon}</span>\n                  <h3 className=\"text-sm font-semibold text-gray-900 mb-1.5\">{p.title}</h3>\n                  <p className=\"text-xs text-gray-500 leading-relaxed\">{p.desc}</p>\n                </div>\n              ))}\n            </div>\n          </section>\n\n          {/* The solution */}\n          <section>\n            <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">What A-Factor does</p>\n            <div className=\"rounded-2xl border border-indigo-100 bg-indigo-50 p-6 sm:p-8\">\n              <div className=\"grid sm:grid-cols-3 gap-6\">\n                {[\n                  { step: '01', title: 'Describe it', desc: 'Type what you want to simulate in English, Yoruba, Hausa, or Igbo.' },\n                  { step: '02', title: 'AI generates it', desc: 'Claude parses your prompt, extracts physics parameters, and builds the simulation instantly.' },\n                  { step: '03', title: 'Learn from it', desc: 'Adjust parameters with sliders, read teacher notes, solve exercises, and share the link with classmates.' },\n                ].map(s => (\n                  <div key={s.step}>\n                    <span className=\"text-2xl font-bold text-indigo-200 block mb-2\">{s.step}</span>\n                    <h3 className=\"text-sm font-semibold text-indigo-900 mb-1\">{s.title}</h3>\n                    <p className=\"text-xs text-indigo-700 leading-relaxed\">{s.desc}</p>\n                  </div>\n                ))}\n              </div>\n            </div>\n          </section>\n\n          {/* Curricula */}\n          <section>\n            <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">Exam curricula supported</p>\n            <div className=\"grid sm:grid-cols-2 lg:grid-cols-3 gap-3\">\n              {CURRICULA.map(c => (\n                <div key={c.name} className={`rounded-xl border p-4 ${c.color}`}>\n                  <p className=\"text-sm font-semibold mb-0.5\">{c.name}</p>\n                  <p className=\"text-xs opacity-70\">{c.desc}</p>\n                </div>\n              ))}\n              <a href={PORTFOLIO_URL} target=\"_blank\" rel=\"noopener noreferrer\"\n                className=\"rounded-xl border border-dashed border-indigo-200 bg-indigo-50/40 p-4 flex flex-col items-center justify-center text-center hover:bg-indigo-50 hover:border-indigo-300 transition group\">\n                <p className=\"text-xs text-indigo-600 font-medium group-hover:text-indigo-700\">More curricula being added — suggest yours</p>\n                <p className=\"text-[10px] text-indigo-400 mt-1\">Reach out via the founder&apos;s portfolio →</p>\n              </a>\n            </div>\n          </section>\n\n          {/* Advanced & undergraduate simulations */}\n          <section>\n            <div className=\"flex items-center gap-2 mb-3\">\n              <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide\">Advanced &amp; undergraduate topics</p>\n              <span className=\"text-[10px] font-medium px-2 py-0.5 rounded-full bg-emerald-100 text-emerald-700\">New</span>\n            </div>\n            <div className=\"grid sm:grid-cols-2 gap-3\">\n              {ADVANCED_SIMS.map(s => (\n                <Link key={s.name} href={s.href}\n                  className=\"rounded-xl border border-gray-200 bg-white p-4 hover:border-indigo-200 hover:bg-indigo-50/30 transition\">\n                  <p className=\"text-sm font-semibold text-gray-900 mb-0.5\">{s.name}</p>\n                  <p className=\"text-xs text-gray-500 leading-relaxed\">{s.desc}</p>\n                </Link>\n              ))}\n            </div>\n            <p className=\"text-[10px] text-gray-400 mt-2\">\n              Newly added for JUPEB and undergraduate-level classes — beyond the core WAEC/NECO/IGCSE curriculum.\n            </p>\n          </section>\n\n          {/* Roadmap */}\n          <section>\n            <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-4\">Product roadmap</p>\n            <div className=\"space-y-3\">\n              {ROADMAP.map((phase, i) => (\n                <div key={i} className=\"rounded-2xl border border-gray-200 bg-white p-5\">\n                  <div className=\"flex items-start justify-between gap-3 mb-3\">\n                    <div>\n                      <div className=\"flex items-center gap-2 mb-1\">\n                        <span className={`text-[10px] font-medium px-2 py-0.5 rounded-full flex items-center gap-1.5 ${STATUS_STYLES[phase.status]}`}>\n                          <span className={`h-1.5 w-1.5 rounded-full ${STATUS_DOT[phase.status]} ${phase.status === 'live' ? 'animate-pulse' : ''}`}/>\n                          {phase.status === 'live' ? 'Live now' : phase.status === 'building' ? 'In progress' : 'Planned'}\n                        </span>\n                        <span className=\"text-xs text-gray-400\">{phase.phase}</span>\n                      </div>\n                      <h3 className=\"text-sm font-semibold text-gray-900\">{phase.title}</h3>\n                    </div>\n                  </div>\n                  <div className=\"flex flex-wrap gap-2\">\n                    {phase.items.map(item => (\n                      <span key={item} className=\"rounded-full bg-gray-50 border border-gray-100 px-3 py-1 text-xs text-gray-600\">\n                        {item}\n                      </span>\n                    ))}\n                  </div>\n                </div>\n              ))}\n            </div>\n          </section>\n\n          {/* Team */}\n          <section>\n            <p className=\"text-xs font-medium text-gray-400 uppercase tracking-wide mb-3\">The team</p>\n            {TEAM.map(t => (\n              <div key={t.name} className=\"rounded-2xl border border-gray-200 bg-white p-5 flex gap-4 items-start\">\n                <div className=\"h-10 w-10 rounded-xl bg-indigo-100 flex items-center justify-center shrink-0\">\n                  <span className=\"text-sm font-semibold text-indigo-600\">{t.name[0]}</span>\n                </div>\n                <div>\n                  <p className=\"text-sm font-semibold text-gray-900\">{t.name}</p>\n                  <p className=\"text-xs text-indigo-600 mb-2\">{t.role}</p>\n                  <p className=\"text-xs text-gray-500 leading-relaxed mb-2\">{t.bio}</p>\n                  <a href={PORTFOLIO_URL} target=\"_blank\" rel=\"noopener noreferrer\"\n                    className=\"inline-flex items-center gap-1 text-xs font-medium text-indigo-600 hover:text-indigo-700\">\n                    View portfolio ↗\n                  </a>\n                </div>\n              </div>\n            ))}\n          </section>\n\n          {/* CTA */}\n          <section className=\"rounded-2xl border border-indigo-100 bg-gradient-to-br from-indigo-50 to-white p-6 sm:p-8 text-center\">\n            <h2 className=\"text-base sm:text-xl font-semibold text-gray-900 mb-2\">\n              Ready to see physics come alive?\n            </h2>\n            <p className=\"text-xs sm:text-sm text-gray-500 mb-6 max-w-md mx-auto\">\n              Try a simulation now — no signup required. Just type what you want to see.\n            </p>\n            <div className=\"flex flex-col sm:flex-row gap-3 justify-center\">\n              <Link href=\"/\"\n                className=\"rounded-xl bg-indigo-600 px-6 py-3 text-sm font-medium text-white hover:bg-indigo-700 transition\">\n                Start simulating\n              </Link>\n              <Link href=\"/simulations\"\n                className=\"rounded-xl border border-gray-200 bg-white px-6 py-3 text-sm font-medium text-gray-700 hover:bg-gray-50 transition\">\n                Browse simulations\n              </Link>\n            </div>\n          </section>\n\n        </div>\n\n        {/* Footer */}\n        <footer className=\"border-t border-gray-200 bg-white mt-10\">\n          <div className=\"mx-auto max-w-4xl px-4 sm:px-6 py-6 flex flex-col sm:flex-row items-center justify-between gap-3 text-xs text-gray-400\">\n            <div className=\"flex items-center gap-2\">\n              <Image src=\"/icon.png\" alt=\"A-Factor STEM Studio\" width={20} height={20}\n                className=\"h-5 w-5 rounded\" />\n              <span className=\"font-medium text-gray-600\">A-Factor STEM Studio</span>\n              <span>© {new Date().getFullYear()} A-Factor EdTech Solutions</span>\n            </div>\n            <div className=\"flex gap-4 items-center\">\n              <Link href=\"/\" className=\"hover:text-indigo-600 transition\">Home</Link>\n              <Link href=\"/simulations\" className=\"hover:text-indigo-600 transition\">Simulations</Link>\n              <Link href=\"/about\" className=\"hover:text-indigo-600 transition\">About</Link>\n              <a href={PORTFOLIO_URL} target=\"_blank\" rel=\"noopener noreferrer\" className=\"hover:text-indigo-600 transition\">Portfolio ↗</a>\n              <Link href=\"/privacy/analytics\" className=\"hover:text-indigo-600 transition\">Usage privacy</Link>\n              <Link href=\"/minitab/admin/login\" className=\"text-gray-300 hover:text-gray-500 transition\">Instructor Login</Link>\n            </div>\n          </div>\n        </footer>\n\n      </main>\n    </>\n  );\n}\n", "src/app/api/minitab-analytics/route.ts": "import { NextRequest, NextResponse } from 'next/server';\nimport { getAnalyticsSummary } from '@/lib/analytics/redis';\nimport { siteAdmin } from '@/lib/analytics/site-auth';\nexport const dynamic='force-dynamic';\nexport async function GET(req:NextRequest) {\n if(!await siteAdmin(req))return NextResponse.json({error:'Admin access required.'},{status:401,headers:{'Cache-Control':'private, no-store'}});\n return NextResponse.json(await getAnalyticsSummary(),{headers:{'Cache-Control':'private, no-store'}});\n}\n", "src/app/api/site-analytics/route.ts": "import {NextRequest,NextResponse} from 'next/server';\nimport {siteAdmin} from '@/lib/analytics/site-auth';\nimport {siteSummary,sitePersonDetail} from '@/lib/analytics/site-store';\nexport const dynamic='force-dynamic';\nexport const runtime='nodejs';\nconst headers={'Cache-Control':'private, no-store'};\nexport async function GET(req:NextRequest){\n if(!await siteAdmin(req))return NextResponse.json({error:'Admin access required.'},{status:401,headers});\n const days=Number(req.nextUrl.searchParams.get('days')||30);if(![7,30,90].includes(days))return NextResponse.json({error:'Choose 7, 30 or 90 days.'},{status:400,headers});\n const id=req.nextUrl.searchParams.get('visitor');if(id&&!/^[a-f0-9]{64}$/.test(id))return NextResponse.json({error:'Invalid visitor.'},{status:400,headers});\n try{return NextResponse.json(id?await sitePersonDetail(id,days):await siteSummary(days),{headers});}catch{return NextResponse.json({error:'Analytics storage is temporarily unavailable. Try refresh.'},{status:503,headers});}\n}\n", "src/app/api/minitab-auth/route.ts": "import { NextRequest, NextResponse } from 'next/server';\nimport { hashPasscode, MINITAB_COOKIE, MINITAB_NAME_COOKIE } from '@/lib/utils/minitabAuth';\nimport { optedOut } from '@/lib/analytics/site-auth';\nimport { recordLogin, sanitizeName } from '@/lib/analytics/redis';\n\nexport async function POST(req: NextRequest) {\n  try {\n    const body = (await req.json()) as { passcode?: string; name?: string };\n    const expected = process.env.MINITAB_PASSCODE;\n\n    if (!expected) {\n      console.error('[minitab-auth] MINITAB_PASSCODE is not set in the environment.');\n      return NextResponse.json({ error: 'Access is not configured yet.' }, { status: 500 });\n    }\n    if (!body.passcode || typeof body.passcode !== 'string') {\n      return NextResponse.json({ error: 'Passcode is required.' }, { status: 400 });\n    }\n    const name = sanitizeName(typeof body.name === 'string' ? body.name : '');\n    if (!name) {\n      return NextResponse.json({ error: 'Please enter your name.' }, { status: 400 });\n    }\n    if (body.passcode !== expected) {\n      return NextResponse.json({ error: 'Incorrect passcode.' }, { status: 401 });\n    }\n\n    const token = await hashPasscode(expected);\n    const res = NextResponse.json({ ok: true });\n    res.cookies.set(MINITAB_COOKIE, token, {\n      httpOnly: true,\n      secure: process.env.NODE_ENV === 'production',\n      sameSite: 'lax',\n      path: '/',\n      maxAge: 60 * 60 * 24 * 30, // 30 days — students shouldn't need to re-enter it every visit\n    });\n    // Readable by client JS is unnecessary here — only the server (tracking\n    // routes) needs this, so it stays httpOnly like the access cookie.\n    res.cookies.set(MINITAB_NAME_COOKIE, encodeURIComponent(name), {\n      httpOnly: true,\n      secure: process.env.NODE_ENV === 'production',\n      sameSite: 'lax',\n      path: '/',\n      maxAge: 60 * 60 * 24 * 30,\n    });\n\n    // Best-effort with a bounded storage timeout; failures do not reject login.\n    if(!optedOut(req))await recordLogin(name);\n\n    return res;\n  } catch (error) {\n    console.error('[minitab-auth] Error', error);\n    return NextResponse.json({ error: 'Something went wrong.' }, { status: 500 });\n  }\n}\n\n// Logout: clear the access cookie. Using DELETE keeps this in the same route\n// as POST (login) — one file for the whole \"session\" resource — rather than\n// a second, separate endpoint.\nexport async function DELETE() {\n  const res = NextResponse.json({ ok: true });\n  res.cookies.set(MINITAB_COOKIE, '', {\n    httpOnly: true,\n    secure: process.env.NODE_ENV === 'production',\n    sameSite: 'lax',\n    path: '/',\n    maxAge: 0, // expire immediately\n  });\n  res.cookies.set(MINITAB_NAME_COOKIE, '', {\n    httpOnly: true,\n    secure: process.env.NODE_ENV === 'production',\n    sameSite: 'lax',\n    path: '/',\n    maxAge: 0,\n  });\n  return res;\n}\n", "src/app/api/minitab-track/route.ts": "import { NextRequest, NextResponse } from 'next/server';\nimport { recordVisit } from '@/lib/analytics/redis';\nimport { analyticsName, optedOut, siteAdmin } from '@/lib/analytics/site-auth';\nimport { SITE_PATHS } from '@/lib/analytics/site-model';\n\nconst SESSION_COOKIE = 'af2s_minitab_sid';\n\nexport async function POST(req: NextRequest) {\n  try {\n    if(req.headers.get('origin')!==new URL(req.url).origin)return NextResponse.json({ok:false},{status:403});\n    if(optedOut(req)||await siteAdmin(req))return NextResponse.json({ok:true});\n    const verifiedName=await analyticsName(req);if(!verifiedName)return NextResponse.json({ok:false},{status:401});\n    const body = (await req.json()) as { slug?: string };\n    if (!body.slug || typeof body.slug !== 'string') {\n      return NextResponse.json({ error: 'slug is required.' }, { status: 400 });\n    }\n    const sessionId = req.cookies.get(SESSION_COOKIE)?.value;\n    if(!Object.hasOwn(SITE_PATHS,body.slug==='hub'?'/minitab':'/minitab/'+body.slug))return NextResponse.json({ok:false},{status:400});\n    // Best-effort — never blocks or errors out the page for the student if\n    // this fails; a missed analytics beacon is not worth a broken page.\n    await recordVisit(body.slug, sessionId, verifiedName);\n\n    return NextResponse.json({ ok: true });\n  } catch (error) {\n    console.error('[minitab-track] Error', error);\n    return NextResponse.json({ ok: false });\n  }\n}\n", "src/app/api/site-track/route.ts": "import {NextRequest,NextResponse} from 'next/server';\nimport {sitePath,siteKinds,type SiteKind} from '@/lib/analytics/site-model';\nimport {recordSite,siteRedis} from '@/lib/analytics/site-store';\nimport {analyticsName,analyticsSecret,analyticsVisitorKey,optedOut,signedAnalyticsId,siteAdmin,SITE_VISITOR_COOKIE,SITE_SESSION_COOKIE,SITE_OPTOUT_COOKIE} from '@/lib/analytics/site-auth';\nexport const runtime='nodejs';\nconst noStore={'Cache-Control':'private, no-store'};\nfunction response(data:object,status=200){return NextResponse.json(data,{status,headers:noStore});}\nfunction sameOrigin(req:NextRequest){return req.headers.get('origin')===new URL(req.url).origin;}\nconst uuid=(s:unknown):s is string=>typeof s==='string'&&/^[a-f0-9]{8}(?:-[a-f0-9]{4}){3}-[a-f0-9]{12}$/i.test(s);\nexport async function POST(req:NextRequest){\n if(!sameOrigin(req))return response({error:'Origin rejected.'},403);\n if(optedOut(req)||/bot|spider|crawl|headless|preview|lighthouse/i.test(req.headers.get('user-agent')||''))return response({accepted:false});\n if(!analyticsSecret()||!siteRedis())return response({accepted:false,configured:false});\n try{\n  if(await siteAdmin(req))return response({accepted:false});\n  const text=await req.text();if(text.length>2048)return response({error:'Event too large.'},413);\n  let b;try{b=JSON.parse(text);}catch{return response({error:'Invalid JSON.'},400);}if(!b||typeof b!=='object'||Array.isArray(b))return response({error:'Invalid event.'},400);const path=sitePath(b.path);\n  if(!path||!uuid(b.id)||!uuid(b.viewId)||!siteKinds.includes(b.kind))return response({error:'Invalid event.'},400);\n  const visitor=signedAnalyticsId(req.cookies.get(SITE_VISITOR_COOKIE)?.value),session=signedAnalyticsId(req.cookies.get(SITE_SESSION_COOKIE)?.value);\n  const ua=req.headers.get('user-agent')||'';const device=/ipad|tablet/i.test(ua)?'Tablet':/mobile|android|iphone/i.test(ua)?'Mobile':'Desktop / other';\n  let referrer='Direct / internal';try{const url=new URL(String(b.referrer||''));if(['http:','https:'].includes(url.protocol)&&url.origin!==new URL(req.url).origin)referrer=url.hostname.slice(0,100);}catch{}\n  const seconds=typeof b.seconds==='number'&&Number.isFinite(b.seconds)?Math.max(0,Math.min(1800,Math.floor(b.seconds))):0;\n  const result=await recordSite({id:b.id,viewId:b.viewId,visitor:analyticsVisitorKey(visitor.id),session:analyticsVisitorKey(session.id),path,kind:b.kind as SiteKind,seconds,name:await analyticsName(req),device,referrer});\n  if(result===-1)return response({accepted:false},429);\n  const res=response({accepted:true});const opts={httpOnly:true,secure:process.env.NODE_ENV==='production',sameSite:'lax' as const,path:'/'};\n  if(visitor.fresh)res.cookies.set(SITE_VISITOR_COOKIE,visitor.cookie,{...opts,maxAge:90*86400});\n  res.cookies.set(SITE_SESSION_COOKIE,session.cookie,{...opts,maxAge:1800});return res;\n }catch{return response({accepted:false},503);}\n}\nexport async function DELETE(req:NextRequest){\n if(!sameOrigin(req))return response({error:'Origin rejected.'},403);\n const res=response({ok:true});const opts={httpOnly:true,secure:process.env.NODE_ENV==='production',sameSite:'lax' as const,path:'/'};\n res.cookies.set(SITE_VISITOR_COOKIE,'',{...opts,maxAge:0});res.cookies.set(SITE_SESSION_COOKIE,'',{...opts,maxAge:0});res.cookies.set(SITE_OPTOUT_COOKIE,'1',{...opts,maxAge:365*86400});return res;\n}\nexport async function PUT(req:NextRequest){\n if(!sameOrigin(req))return response({error:'Origin rejected.'},403);\n const res=response({ok:true});res.cookies.set(SITE_OPTOUT_COOKIE,'',{httpOnly:true,secure:process.env.NODE_ENV==='production',sameSite:'lax',path:'/',maxAge:0});return res;\n}\n", "src/app/minitab/admin/page.tsx": "'use client';\nimport Link from 'next/link';\nimport { useState, useEffect } from 'react';\nimport { useRouter } from 'next/navigation';\nimport { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';\nimport { AppHeader } from '@/components/layout/AppHeader';\n\ninterface StudentSummary {\n  name: string;\n  logins: number;\n  visits: number;\n  lastActive: number | null;\n}\n\ninterface AnalyticsSummary {\n  configured: boolean;\n  totalLogins: number;\n  distinctSessions: number;\n  visitsBySlug: { slug: string; count: number }[];\n  students: StudentSummary[];\n  recentEvents: { t: number; kind: 'login' | 'visit'; slug?: string; name?: string }[];\n}\n\nconst SLUG_LABELS: Record<string, string> = {\n  'gradient-explorer': 'Gradient Explorer',\n  'div-stokes': 'Divergence & Stokes',\n  'eigenvector-explorer': 'Eigenvector Explorer',\n  'gamma-function': 'Gamma Function',\n  'legendre-bessel': 'Legendre & Bessel',\n  'hermite-laguerre-delta': 'Hermite/Laguerre/Delta',\n  'fourier-series': 'Fourier Series',\n  'fourier-transform': 'Fourier Transform',\n  'damped-oscillator': 'Damped Oscillator',\n  hub: 'Library hub page',\n};\n\nfunction timeAgo(ts: number | null): string {\n  if (!ts) return 'never';\n  const s = Math.floor((Date.now() - ts) / 1000);\n  if (s < 60) return `${s}s ago`;\n  const m = Math.floor(s / 60);\n  if (m < 60) return `${m}m ago`;\n  const h = Math.floor(m / 60);\n  if (h < 24) return `${h}h ago`;\n  return `${Math.floor(h / 24)}d ago`;\n}\n\nexport default function MinitabAnalyticsPage() {\n  const router = useRouter();\n  const [data, setData] = useState<AnalyticsSummary | null>(null);\n  const [loading, setLoading] = useState(true);\n  const [loggingOut, setLoggingOut] = useState(false);\n\n  useEffect(() => {\n    fetch('/api/minitab-analytics')\n      .then(r => r.json())\n      .then(setData)\n      .finally(() => setLoading(false));\n  }, []);\n\n  const logout = async () => {\n    setLoggingOut(true);\n    try {\n      await fetch('/api/minitab-admin-auth', { method: 'DELETE' });\n    } finally {\n      router.push('/minitab/admin/login');\n      router.refresh();\n    }\n  };\n\n  return (\n    <>\n      <AppHeader />\n      <main className=\"min-h-screen bg-gray-50\">\n        <section className=\"border-b border-gray-200 bg-white\">\n          <div className=\"mx-auto max-w-5xl px-4 sm:px-6 py-6 flex items-start justify-between gap-4\">\n            <div>\n              <p className=\"text-xs text-gray-400 mb-1\">PHY 403 · Instructor only</p>\n              <h1 className=\"text-xl font-semibold text-gray-900\">Activity Dashboard</h1>\n              <p className=\"text-sm text-gray-500 mt-1\">Per-student logins and simulation visits, from the name each student entered at login.</p>\n            </div>\n            <button onClick={logout} disabled={loggingOut}\n              className=\"text-xs text-gray-400 hover:text-gray-700 underline underline-offset-2 shrink-0 mt-1\">\n              {loggingOut ? 'Logging out…' : 'Logout'}\n            </button>\n          </div>\n        </section>\n\n        <div className=\"mx-auto max-w-5xl px-4 sm:px-6 py-6 space-y-4\"><Link href=\"/minitab/admin/site-analytics\" className=\"block rounded-2xl border border-indigo-200 bg-indigo-50 p-5 text-indigo-900\"><strong>Site-wide usage analytics →</strong><p className=\"mt-2 text-sm\">Popular pages, visitor trends, activity and browser-level page histories across all subjects.</p></Link>\n          {loading && <p className=\"text-sm text-gray-400\">Loading…</p>}\n\n          {!loading && data && !data.configured && (\n            <div className=\"rounded-2xl border border-amber-200 bg-amber-50 p-5\">\n              <p className=\"text-sm font-medium text-amber-800 mb-1\">Analytics isn&apos;t connected yet</p>\n              <p className=\"text-xs text-amber-700 leading-relaxed\">\n                Add <code className=\"bg-amber-100 px-1 rounded\">UPSTASH_REDIS_REST_URL</code> and{' '}\n                <code className=\"bg-amber-100 px-1 rounded\">UPSTASH_REDIS_REST_TOKEN</code> to your environment\n                and redeploy — tracking starts automatically from the next login onward.\n              </p>\n            </div>\n          )}\n\n          {!loading && data && data.configured && (\n            <>\n              <div className=\"grid grid-cols-3 gap-4\">\n                <div className=\"rounded-2xl border border-gray-200 bg-white p-5\">\n                  <p className=\"text-xs text-gray-400 uppercase tracking-wide mb-1\">Total logins</p>\n                  <p className=\"text-3xl font-semibold text-gray-900\">{data.totalLogins}</p>\n                </div>\n                <div className=\"rounded-2xl border border-gray-200 bg-white p-5\">\n                  <p className=\"text-xs text-gray-400 uppercase tracking-wide mb-1\">Named students</p>\n                  <p className=\"text-3xl font-semibold text-gray-900\">{data.students.length}</p>\n                </div>\n                <div className=\"rounded-2xl border border-gray-200 bg-white p-5\">\n                  <p className=\"text-xs text-gray-400 uppercase tracking-wide mb-1\">Distinct devices</p>\n                  <p className=\"text-3xl font-semibold text-gray-900\">{data.distinctSessions}</p>\n                </div>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-5\">\n                <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">Students</p>\n                {data.students.length === 0 ? (\n                  <p className=\"text-xs text-gray-400\">No students have logged in yet.</p>\n                ) : (\n                  <table className=\"w-full text-xs\">\n                    <thead>\n                      <tr className=\"text-left text-gray-400 border-b border-gray-100\">\n                        <th className=\"pb-2 font-medium\">Name</th>\n                        <th className=\"pb-2 font-medium text-right\">Logins</th>\n                        <th className=\"pb-2 font-medium text-right\">Visits</th>\n                        <th className=\"pb-2 font-medium text-right\">Last active</th>\n                      </tr>\n                    </thead>\n                    <tbody>\n                      {data.students.map(s => (\n                        <tr key={s.name} className=\"border-b border-gray-50 last:border-0\">\n                          <td className=\"py-2 text-gray-800 font-medium\">{s.name}</td>\n                          <td className=\"py-2 text-right text-gray-600 tabular-nums\">{s.logins}</td>\n                          <td className=\"py-2 text-right text-gray-600 tabular-nums\">{s.visits}</td>\n                          <td className=\"py-2 text-right text-gray-400 tabular-nums\">{timeAgo(s.lastActive)}</td>\n                        </tr>\n                      ))}\n                    </tbody>\n                  </table>\n                )}\n                <p className=\"text-[11px] text-gray-400 mt-3\">\n                  Names are self-reported at login (not verified) — a student using a different name or device twice will appear as separate rows.\n                </p>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-5\">\n                <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">Visits per simulation</p>\n                <ResponsiveContainer width=\"100%\" height={280}>\n                  <BarChart data={data.visitsBySlug.map(v => ({ name: SLUG_LABELS[v.slug] ?? v.slug, count: v.count }))} layout=\"vertical\" margin={{ left: 20 }}>\n                    <CartesianGrid strokeDasharray=\"3 3\" stroke=\"#f0f0f0\" />\n                    <XAxis type=\"number\" tick={{ fontSize: 11 }} allowDecimals={false} />\n                    <YAxis type=\"category\" dataKey=\"name\" tick={{ fontSize: 11 }} width={150} />\n                    <Tooltip />\n                    <Bar dataKey=\"count\" fill=\"#6366f1\" radius={[0, 4, 4, 0]} />\n                  </BarChart>\n                </ResponsiveContainer>\n              </div>\n\n              <div className=\"rounded-2xl border border-gray-200 bg-white p-5\">\n                <p className=\"text-xs font-medium text-gray-500 uppercase tracking-wide mb-3\">Recent activity</p>\n                {data.recentEvents.length === 0 ? (\n                  <p className=\"text-xs text-gray-400\">No activity recorded yet.</p>\n                ) : (\n                  <div className=\"space-y-1 max-h-96 overflow-y-auto\">\n                    {data.recentEvents.map((e, i) => (\n                      <div key={i} className=\"flex justify-between items-center text-xs py-1.5 border-b border-gray-50 last:border-0\">\n                        <span className=\"text-gray-600\">\n                          {e.kind === 'login'\n                            ? `🔑 ${e.name ?? 'Someone'} logged in`\n                            : `📊 ${e.name ?? 'Someone'} opened ${SLUG_LABELS[e.slug ?? ''] ?? e.slug}`}\n                        </span>\n                        <span className=\"text-gray-400 tabular-nums\">{timeAgo(e.t)}</span>\n                      </div>\n                    ))}\n                  </div>\n                )}\n              </div>\n            </>\n          )}\n        </div>\n      </main>\n    </>\n  );\n}\n", "src/app/minitab/admin/site-analytics/page.tsx": "'use client';\nimport {useEffect,useState} from 'react';\nimport Link from 'next/link';\nimport {AppHeader} from '@/components/layout/AppHeader';\nimport {csvCell,type SiteSummary,type SitePersonDetail,type SiteRow} from '@/lib/analytics/site-model';\nconst time=(seconds:number)=>`${(seconds/60).toFixed(1)} min`;\nconst label=(id:string,name:string)=>name?`${name} (self-reported)`:`Browser ${id.slice(0,8)}`;\nexport default function SiteAnalyticsPage(){\n const [days,setDays]=useState(30),[refresh,setRefresh]=useState(0),[data,setData]=useState<SiteSummary|null>(null),[error,setError]=useState(''),[loading,setLoading]=useState(true),[selected,setSelected]=useState(''),[detail,setDetail]=useState<SitePersonDetail|null>(null),[detailError,setDetailError]=useState('');\n useEffect(()=>{const controller=new AbortController();setLoading(true);setError('');setSelected('');setDetail(null);fetch(`/api/site-analytics?days=${days}`,{cache:'no-store',signal:controller.signal}).then(async r=>{if(r.status===401){window.location.assign('/minitab/admin/login');throw Error('Please sign in as an instructor.');}const body=await r.json();if(!r.ok)throw Error(body.error||'Could not load analytics.');return body;}).then(setData).catch(e=>{if(e.name!=='AbortError')setError(e.message);}).finally(()=>{if(!controller.signal.aborted)setLoading(false);});return()=>controller.abort();},[days,refresh]);\n useEffect(()=>{if(!selected)return;const controller=new AbortController();setDetail(null);setDetailError('');fetch(`/api/site-analytics?days=${days}&visitor=${encodeURIComponent(selected)}`,{cache:'no-store',signal:controller.signal}).then(async r=>{const body=await r.json();if(!r.ok)throw Error(body.error||'Could not load browser history.');return body;}).then(setDetail).catch(e=>{if(e.name!=='AbortError')setDetailError(e.message);});return()=>controller.abort();},[selected,days]);\n function download(){if(!data)return;const rows=[['Page','Path','Views','Visible seconds'],...data.pages.map(p=>[p.title,p.key,p.count,p.seconds])];const blob=new Blob(['\\uFEFF'+rows.map(row=>row.map(csvCell).join(',')).join('\\r\\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`afactor-pages-${days}-days.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}\n function breakdown(title:string,rows:SiteRow[]){return <section className=\"rounded-xl border bg-white p-4\"><h2 className=\"font-semibold text-lg\">{title}</h2><ul className=\"mt-3 space-y-2\">{rows.length?rows.map(r=><li key={r.key} className=\"flex justify-between gap-4 break-all\"><span>{r.key}</span><strong>{r.count.toLocaleString()}</strong></li>):<li>No activity yet.</li>}</ul></section>;}\n return <><AppHeader/><main className=\"mx-auto max-w-7xl space-y-6 px-4 py-8 text-slate-900\"><Link href=\"/minitab/admin\" className=\"text-blue-700 underline\">← Minitab dashboard</Link><div className=\"flex flex-wrap items-center justify-between gap-4\"><div><h1 className=\"text-3xl font-bold\">Site usage</h1><p className=\"mt-2 text-slate-600\">Popular activities and audience visits across A-Factor.</p></div><div className=\"flex flex-wrap items-center gap-3\"><label>Period <select className=\"rounded border bg-white p-2 text-slate-900\" value={days} onChange={e=>setDays(Number(e.target.value))}>{[7,30,90].map(n=><option key={n} value={n}>Last {n} days</option>)}</select></label><button className=\"rounded border bg-white px-4 py-2 disabled:opacity-50\" disabled={loading} onClick={()=>setRefresh(n=>n+1)}>Refresh</button><button className=\"rounded bg-blue-700 px-4 py-2 text-white disabled:opacity-50\" disabled={loading||!!error||!data?.configured} onClick={download}>Export pages CSV</button></div></div>\n {loading&&<p role=\"status\">Loading usage reports…</p>}{error&&<p role=\"alert\" className=\"rounded border border-red-300 bg-red-50 p-4\">{error}</p>}\n {!loading&&!error&&data&&!data.configured&&<section className=\"rounded-xl border bg-white p-6\"><h2 className=\"font-semibold\">Connect analytics storage</h2><p className=\"mt-2\">Set UPSTASH_REDIS_REST_URL and UPSTASH_REDIS_REST_TOKEN (or KV_REST_API_URL and KV_REST_API_TOKEN), plus MINITAB_ADMIN_PASSCODE in your deployment environment, then redeploy. Reports begin when tracking is enabled.</p></section>}\n {!loading&&!error&&data?.configured&&<><div className=\"grid grid-cols-2 gap-3 lg:grid-cols-4\">{[['Page views',data.views.toLocaleString()],['Estimated browsers',data.visitors.toLocaleString()],['Estimated sessions',data.sessions.toLocaleString()],['Visible, focused time',time(data.seconds)]].map(([title,value])=><section key={title} className=\"rounded-xl border bg-white p-4\"><p className=\"text-sm text-slate-600\">{title}</p><strong className=\"mt-2 block text-2xl\">{value}</strong></section>)}</div>\n <section className=\"rounded-xl border bg-white p-4\"><h2 className=\"text-lg font-semibold\">Daily page views</h2><p className=\"text-sm text-slate-600\">Days use UTC; the current day is incomplete.</p><div className=\"mt-4 max-h-72 overflow-auto space-y-2\">{data.daily.map(d=><div key={d.day} className=\"flex items-center gap-3 text-sm\"><span className=\"w-24 shrink-0\">{d.day}</span><div className=\"h-4 flex-1 rounded bg-slate-100\"><div className=\"h-4 rounded bg-blue-600\" style={{width:`${d.views/Math.max(1,...data.daily.map(x=>x.views))*100}%`}}/></div><span className=\"w-12 text-right\">{d.views}</span></div>)}</div></section>\n <section className=\"rounded-xl border bg-white p-4\"><h2 className=\"text-lg font-semibold\">Most viewed pages</h2><div className=\"overflow-x-auto\"><table className=\"mt-3 w-full text-left text-sm\"><thead><tr><th className=\"p-2\">Page</th><th className=\"p-2\">Views</th><th className=\"p-2\">Visible time</th></tr></thead><tbody>{data.pages.map(p=><tr key={p.key} className=\"border-t\"><td className=\"p-2\"><Link className=\"text-blue-700 underline\" href={p.key}>{p.title}</Link><span className=\"block break-all text-xs text-slate-500\">{p.key}</span></td><td className=\"p-2\">{p.count}</td><td className=\"whitespace-nowrap p-2\">{time(p.seconds)}</td></tr>)}</tbody></table>{!data.pages.length&&<p>No visits recorded in this period.</p>}</div></section>\n <div className=\"grid gap-4 md:grid-cols-2\">{breakdown('Subject page views',data.subjects)}{breakdown('Device categories',data.devices)}{breakdown('Referring hosts · page views',data.referrers)}{breakdown('Simulation button actions',data.actions)}</div>\n <section className=\"rounded-xl border bg-white p-4\"><h2 className=\"text-lg font-semibold\">Recent browsers</h2><p className=\"text-sm text-slate-600\">Up to 200 active browser profiles in this period. Select one to see its pages. A shared browser may represent several students.</p><ul className=\"mt-3 max-h-80 overflow-auto divide-y\">{data.people.map(p=><li key={p.id}><button onClick={()=>setSelected(p.id)} aria-pressed={selected===p.id} className={`w-full rounded p-3 text-left ${selected===p.id?'bg-blue-50':'hover:bg-slate-50'}`}><strong>{label(p.id,p.name)}</strong><span className=\"block break-all text-sm text-slate-600\">{p.device} · {new Date(p.last).toLocaleString()} · {p.path}</span></button></li>)}</ul>{selected&&<div className=\"mt-4 rounded border p-4\" aria-live=\"polite\"><h3 className=\"font-semibold\">{detail?.person?label(selected,detail.person.name):'Browser history'}</h3>{detailError?<p role=\"alert\">{detailError}</p>:!detail?<p>Loading history…</p>:<><p className=\"my-2\">{detail.views} views · {time(detail.seconds)} visible time in the selected period.</p><ul className=\"space-y-2\">{detail.pages.map(p=><li key={p.key} className=\"flex flex-wrap justify-between gap-2\"><span className=\"break-all\">{p.title} <small>({p.key})</small></span><strong>{p.count} views · {time(p.seconds)}</strong></li>)}</ul></>}</div>}</section>\n <section className=\"rounded-xl border bg-white p-4\"><h2 className=\"text-lg font-semibold\">Latest activity</h2><p className=\"text-sm text-slate-600\">Latest 100 events available in this period; time updates are excluded.</p><ul className=\"mt-3 max-h-80 overflow-auto divide-y\">{data.recent.map((e,i)=><li key={`${e.t}-${e.visitor}-${i}`} className=\"py-2 text-sm\"><strong>{label(e.visitor,e.name)}</strong> · {e.kind}<span className=\"block break-all text-slate-600\">{e.path} · {new Date(e.t).toLocaleString()}</span></li>)}</ul></section>\n <p className=\"text-sm text-slate-600\">Reports start after installation; earlier visits cannot be recovered. Browser and session counts are estimates, not verified people or attendance. Names come from student sign-in and are self-reported. Visible time is capped at 30 minutes per page view and does not prove learning. Privacy preferences, blocked cookies and blockers can reduce counts. Embedded pages count separately from their parent page. Action counts cover recognised simulation controls. Historical Minitab counters remain separate. <Link className=\"underline\" href=\"/privacy/analytics\">Usage privacy and tracking preference</Link></p></>}\n </main></>;\n}\n", "src/app/privacy/analytics/page.tsx": "'use client';\nimport {useEffect,useState} from 'react';\nimport Link from 'next/link';\nimport {AppHeader} from '@/components/layout/AppHeader';\nexport default function AnalyticsPrivacy(){\n const [off,setOff]=useState(false),[error,setError]=useState(''),[busy,setBusy]=useState(false);\n useEffect(()=>{try{setOff(localStorage.getItem('afactor-analytics-opt-out-v1')==='1');}catch{}},[]);\n async function update(){setBusy(true);setError('');try{const next=!off;if(next)localStorage.setItem('afactor-analytics-opt-out-v1','1');const res=await fetch('/api/site-track',{method:next?'DELETE':'PUT'});if(!res.ok)throw Error('Unable to save your preference.');if(!next)localStorage.removeItem('afactor-analytics-opt-out-v1');setOff(next);window.dispatchEvent(new Event('afactor-analytics-preference'));}catch{setError('Could not save this preference. Check your connection and retry.');}finally{setBusy(false);}}\n return <><AppHeader/><main className=\"mx-auto max-w-3xl space-y-5 px-4 py-10 text-gray-900\"><h1 className=\"text-2xl font-semibold\">Usage analytics</h1><p>We use first-party usage statistics to improve lessons and understand which activities students and visitors use. The instructor can see page visits, broad device categories, referrer hostnames, estimated browser/session counts, visible time, and selected simulation actions.</p><p>Public visitors receive a random browser identifier. If you have signed into Minitab, activity may be labelled with the name you supplied at login. These names are self-reported, and a shared browser can be used by different people. Analytics does not establish a verified identity or prove learning or attendance.</p><p>We do not record IP addresses, precise location, typed AI prompts, answers, keystrokes, audio or browser fingerprints in these analytics. Our hosting and storage providers may maintain their own operational logs. Usage data is stored in the site’s configured Upstash Redis database.</p><p>Reports cover the most recent 90 days. Daily records expire after 95 days, with a short buffer for reporting. Browser identifiers last up to 90 days; a session expires after 30 minutes without a tracking event. Clearing cookies or changing devices creates a new identifier.</p><p>Tracking respects Do Not Track and Global Privacy Control where the browser supplies them. You can also change the preference for this browser below. Turning tracking off clears its analytics identifier cookies; it does not erase earlier recorded activity.</p><button className=\"min-h-11 rounded-xl bg-indigo-600 px-4 py-2 text-white disabled:opacity-50\" disabled={busy} onClick={update}>{busy?'Saving…':off?'Allow usage analytics':'Turn off usage analytics'}</button><p role=\"status\">{error||`This browser’s preference: ${off?'off':'allowed, subject to browser privacy signals'}.`}</p><p><Link className=\"text-indigo-700 underline\" href=\"/about\">Back to About</Link></p></main></>;\n}\n", "checks/site-analytics.cjs": "const fs=require('fs'),path=require('path'),vm=require('vm'),ts=require('typescript'),assert=require('node:assert/strict');\nfunction load(file,mocks={}){file=path.resolve(file);const mod={exports:{}};const req=id=>{if(id in mocks)return mocks[id];if(id.startsWith('@/'))return load('src/'+id.slice(2)+'.ts',mocks);if(id.startsWith('.')){const p=path.resolve(path.dirname(file),id);return p.endsWith('.json')?JSON.parse(fs.readFileSync(p,'utf8')):load(p+'.ts',mocks);}return require(id);};vm.runInNewContext(ts.transpileModule(fs.readFileSync(file,'utf8'),{compilerOptions:{module:ts.ModuleKind.CommonJS,esModuleInterop:true,resolveJsonModule:true}}).outputText,{module:mod,exports:mod.exports,require:req,process,Buffer,AbortSignal,console,URL,Headers,TextEncoder,crypto:require(\"node:crypto\").webcrypto});return mod.exports;}\n(async()=>{\nconst m=load('src/lib/analytics/site-model.ts');assert.equal(m.sitePath('/'),'/');assert.equal(m.sitePath('/biology/'),'/biology');for(const p of ['/minitab/admin','/privacy/analytics','/minitab/login','/biology?name=Student','/unknown',null,'/__proto__'])assert.equal(m.sitePath(p),null);\nassert.equal(m.dateKeys(7,Date.parse('2026-11-05T00:00:00Z'))[0],'2026-10-30');assert.equal(m.dateKeys(90).length,90);assert.equal(m.csvCell('=SUM(A1)'),`\"'=SUM(A1)\"`);assert.equal(m.csvCell('a\"b'),'\"a\"\"b\"');\nprocess.env.MINITAB_ADMIN_PASSCODE='test-admin-only';process.env.MINITAB_PASSCODE='test-student-only';process.env.ANALYTICS_HASH_SECRET='test-secret-only';\nconst a=load('src/lib/analytics/site-auth.ts'),utils=load('src/lib/utils/minitabAuth.ts');const req=(cookies={},headers={})=>({cookies:{get:k=>cookies[k]===undefined?undefined:{value:cookies[k]}},headers:new Headers(headers)});\nconst signed=a.signedAnalyticsId();assert.equal(a.signedAnalyticsId(signed.cookie).id,signed.id);assert.notEqual(a.signedAnalyticsId(signed.cookie+'x').id,signed.id);assert.match(a.analyticsVisitorKey(signed.id),/^[a-f0-9]{64}$/);assert.equal(await a.siteAdmin(req()),false);assert.equal(await a.siteAdmin(req({[utils.MINITAB_ADMIN_COOKIE]:await utils.hashPasscode('test-admin-only')})),true);assert.equal(await a.analyticsName(req({[utils.MINITAB_NAME_COOKIE]:'Forged'})),'');assert.equal(await a.analyticsName(req({[utils.MINITAB_COOKIE]:await utils.hashPasscode('test-student-only'),[utils.MINITAB_NAME_COOKIE]:'Student%20One'})),'Student One');assert.equal(a.optedOut(req({}, {'dnt':'1'})),true);\nconst s=load('src/lib/analytics/site-store.ts');assert.equal((await s.siteSummary(7,null)).configured,false);let call;await s.recordSite({id:'event',viewId:'view',visitor:'visitor',session:'session',path:'/biology',kind:'pageview',seconds:0,name:'',device:'Mobile',referrer:'Direct / internal'},{eval:async(...args)=>{call=args;return 1;}},Date.parse('2026-11-05T12:00:00Z'));assert.equal(call[1].length,16);assert(call[1][3].endsWith('2026-11-05'));assert.equal(JSON.parse(call[2][0]).subject,'Biology');\nconst pf=[],zs=[];let batch=0;const fake={pipeline(){const commands=[];return{hgetall(k){commands.push(k);return this;},async exec(){batch++;return commands.map(k=>k.includes('day:')?{views:2,seconds:10}:k.includes('pages:')?{'/biology':2}:k.includes('page-time:')?{'/biology':10}:{});}};},pfcount:async(...keys)=>{pf.push(keys);return 3;},zrange:async(...args)=>{zs.push(args);return[];},lrange:async()=>[]};\nconst report=await s.siteSummary(7,fake);assert.equal(report.views,14);assert.equal(report.visitors,3);assert.equal(report.seconds,70);assert.equal(report.pages[0].count,14);assert.equal(pf[0].length,7);assert.equal(zs[0][1],'+inf');assert.equal(zs[0][3].rev,true);\nconst next={NextResponse:{json:(body,opts={})=>({body,status:opts.status||200})}};let accessed=false;const api=load('src/app/api/site-analytics/route.ts',{'next/server':next,'@/lib/analytics/site-auth':{siteAdmin:async()=>false},'@/lib/analytics/site-store':{siteSummary:async()=>{accessed=true;}}});assert.equal((await api.GET({})).status,401);assert.equal(accessed,false);\nconst old=load('src/app/api/minitab-analytics/route.ts',{'next/server':next,'@/lib/analytics/site-auth':{siteAdmin:async()=>false},'@/lib/analytics/redis':{getAnalyticsSummary:async()=>{throw Error('must not read');}}});assert.equal((await old.GET({})).status,401);\nconst track=load('src/app/api/site-track/route.ts',{'next/server':next,'@/lib/analytics/site-auth':{optedOut:()=>false,analyticsSecret:()=> 'test',siteAdmin:async()=>false},'@/lib/analytics/site-store':{siteRedis:()=>({})}});const request=(body,origin='https://example.test')=>({url:'https://example.test/api/site-track',headers:new Headers({origin}),text:async()=>body});assert.equal((await track.POST(request('{}','https://other.test'))).status,403);assert.equal((await track.POST(request('{'))).status,400);assert.equal((await track.POST(request('null'))).status,400);assert.equal((await track.POST(request(JSON.stringify({path:'/minitab/admin',id:'bad'})))).status,400);assert.equal((await track.POST(request('x'.repeat(2049)))).status,413);\nconsole.log('PASS: route allowlist, UTC windows, CSV injection escaping, signed browser IDs, admin/student auth, privacy signals, storage aggregation and both protected reporting APIs.');\n})().catch(e=>{console.error(e);process.exitCode=1;});\n", "docs/site-analytics.md": "# Site-wide analytics\n\nApply the patch from the A-Factor project root, run `npm run build`, then deploy using your normal workflow. Open `/minitab/admin/login`, sign in, and follow **Site-wide usage** to `/minitab/admin/site-analytics`.\n\n## Environment\n\nUse your existing `MINITAB_ADMIN_PASSCODE` and Upstash REST credentials:\n\n- `UPSTASH_REDIS_REST_URL` and `UPSTASH_REDIS_REST_TOKEN`, or\n- `KV_REST_API_URL` and `KV_REST_API_TOKEN`.\n\nOptionally set `ANALYTICS_HASH_SECRET` to a long random secret (for example generate with `openssl rand -hex 32`). Without it, analytics uses the admin passcode. Keep all these values server-side; never prefix them NEXT_PUBLIC. Rotating the hash secret or its fallback starts new browser identities. Existing student names require a valid Minitab access cookie and `MINITAB_PASSCODE`.\n\nRedeploy after changing environment variables. Missing storage shows a setup message; storage failures show an error rather than false zero totals. This patch does not provision storage or change your provider plan. Storage operations count toward your provider usage.\n\n## Reports and interpretation\n\nThe new dashboard reports 7, 30 or 90 UTC days: page views, estimated distinct browsers/sessions (Redis HyperLogLog), focused visible time, popular pages/subjects, broad device type, external referrer hostname, selected simulation actions, latest activity, browser page history and page CSV export. Names are self-reported, not verified students. Browser labels cannot identify every audience member; shared devices may represent several people. These are usage indicators, not attendance or learning assessments.\n\nTracking starts after installation: old site-wide visits cannot be recovered. The existing Minitab dashboard and historical counters remain separate. Embedded pages count independently. Action counts cover recognised Run/Pause/Reset/classroom buttons within simulation stages. Visible time requires a focused, visible tab, is capped at 30 minutes per page view, and can be lost if the browser closes before sending. Referrer hosts describe page-view sources, not verified acquisition attribution.\n\nAdmin sessions, common bots, Do Not Track, Global Privacy Control and browser opt-outs are excluded. Blockers and cookie restrictions may reduce counts. Public telemetry is same-origin, path-allowlisted, rate-limited per signed session, and deduplicated; it is not a fraud-proof measurement system.\n\nReports retain 90 days; daily records expire after 95 days. Browser profiles expire after 95 days without an update. Recent events are capped at 200; the dashboard shows 100. Daily unique-count sketches expire after 95 days. No IP addresses, full query strings, typed prompts/answers, audio, fingerprints or precise location are stored by this feature. Hosting providers may keep operational logs separately.\n\nVisitors can disable tracking at `/privacy/analytics` (linked from About). The preference clears browser analytics IDs and disables future events; it does not delete previously stored history. This preference also suppresses future legacy Minitab counters. Previously collected Minitab records retain their existing lifecycle.\n\nBoth analytics GET endpoints require an instructor cookie and use private no-store responses. No new public name-search endpoint is added.\n\n## Verification after deployment\n\n1. In a signed-out browser, open two topic pages and use a simulation. Keep one tab focused for over a minute.\n2. In a separate instructor browser, refresh the site dashboard and check page counts, visible time and browser history.\n3. In a student browser, sign into Minitab and visit a topic; check the self-reported label. A public visitor remains anonymous.\n4. Confirm `/api/site-analytics` and `/api/minitab-analytics` return 401 in a signed-out browser.\n5. Disable analytics on the privacy page, browse and verify no new events; re-enable to resume with a new browser ID.\n6. Check desktop and mobile layouts, CSV download and 7/30/90-day filters.\n\nLocal validation does not connect to your production Redis or verify real visitor counts. New static public routes should be added to `src/lib/analytics/site-pages.json` when introduced; private routes should remain excluded.\n", ".env.example": "ANTHROPIC_API_KEY=\nNEXT_PUBLIC_APP_NAME=A-Factor STEM Studio\nNEXT_PUBLIC_APP_URL=http://localhost:3000\nMINITAB_PASSCODE=\nUPSTASH_REDIS_REST_URL=\nUPSTASH_REDIS_REST_TOKEN=\nMINITAB_ADMIN_PASSCODE=\n\n# Optional dedicated stable secret for pseudonymous analytics identifiers.\n# If omitted, MINITAB_ADMIN_PASSCODE is used. Rotating the secret resets browser continuity.\nANALYTICS_HASH_SECRET=\n"},expected={"src/app/layout.tsx": "b889aa75ff2c14e117ddf8dff171b13d24911533071681e8d650bc7559df4f53", "src/components/layout/MinitabBar.tsx": "1041a95a194df9045b42cef0774356a54c816a15f2f029837e09523b6334a8af", "src/components/analytics/SiteAnalyticsTracker.tsx": null, "src/lib/analytics/redis.ts": "1bd63c7c1200e4c4988dc83d8709f7b3952e3c0cd811d027f9761583a004320d", "src/lib/analytics/site-auth.ts": null, "src/lib/analytics/site-pages.json": null, "src/lib/analytics/site-model.ts": null, "src/lib/analytics/site-store.ts": null, "src/app/about/page.tsx": "5d93b9397866ab03a376c31ac28a283e698fe12085cfe72506b50be347478de6", "src/app/api/minitab-analytics/route.ts": "3b959a8c4133d448a78508c13a0789498e479dfd226f2d2227797669d1450e28", "src/app/api/site-analytics/route.ts": null, "src/app/api/minitab-auth/route.ts": "b27155a7b34a7145a17caf4e9567db8482e805bef0638268bbfb7cf2f06b9413", "src/app/api/minitab-track/route.ts": "ef3d2b7848f94cd2e300140c602ca4a0b759ddf69b973b2b30c79d790f9fab01", "src/app/api/site-track/route.ts": null, "src/app/minitab/admin/page.tsx": "32eb5a7f534ac5f41daa64b47e5a1d04d3824d41dd98b093d0727970ff449e18", "src/app/minitab/admin/site-analytics/page.tsx": null, "src/app/privacy/analytics/page.tsx": null, "checks/site-analytics.cjs": null, "docs/site-analytics.md": null, ".env.example": "da4df9a899f6a8e67d4d87a495986807bd0a7c81bd9776823d97e7d328b7f297"};
